/**
 * A preview card only ever shows 4 of a symbol's full 11 `condition_chips`. Selection order per
 * the spec: (1) anything in `chips_added` -- these are new signals worth surfacing first, (2)
 * among the rest, BULLISH/BEARISH before NEUTRAL (a directional read is more informative at a
 * glance than a neutral one), (3) ties fall back to the backend's own array order. `sortedWith`
 * is a stable sort, so rule 3 falls out for free once rules 1 and 2 are expressed as the primary/
 * secondary sort keys -- no explicit index bookkeeping needed.
 */
fun selectPreviewChips(
    chips: List<DomainConditionChip>,
    added: Set<String>
): List<DomainConditionChip> {
    return chips
        .sortedWith(
            compareBy(
                { chip -> if (chip.label != null && added.contains(chip.label)) 0 else 1 },
                { chip -> if (chip.direction?.uppercase() == "NEUTRAL") 1 else 0 }
            )
        )
        .take(4)
}

/**
 * The condensed signal-chip row on a `StockPreviewCard`. Colors come straight off `direction`
 * ("BULLISH"/"BEARISH"/"NEUTRAL") against the theme's signal tokens -- the same hand-rolled
 * `when`-on-raw-string pattern `NewsScreen.kt`'s sentiment tags already use, not the
 * `SignalColor`/`SignalColorExtensions` pairing, since that enum's GREEN/YELLOW/RED vocabulary
 * belongs to a different domain model. An unrecognized or null direction falls back to the
 * neutral tokens -- there's no resolved `signal.unknown` chip treatment yet (Design System v1.0
 * still has it as a TODO), so this is the same neutral-fallback the rest of this feature uses.
 *
 * `FlowRow` rather than a scrolling row -- all 4 selected chips should be visible at once without
 * a horizontal swipe; when they don't fit on one line the row wraps to a second instead of
 * clipping or scrolling offscreen.
 */
@Composable
fun ConditionChipRow(
    chips: List<DomainConditionChip>,
    modifier: Modifier = Modifier
) {
    val pulseColors = LocalPulseColors.current

    FlowRow(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small)),
        verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small))
    ) {
        chips.forEach { chip ->
            val (pillColor, textColor) = when (chip.direction?.uppercase()) {
                "BULLISH" -> pulseColors.signalBullishPill to pulseColors.signalBullishText
                "BEARISH" -> pulseColors.signalBearishPill to pulseColors.signalBearishText
                else -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
            }

            SignalPill(
                text = chip.label.orEmpty(),
                pillColor = pillColor,
                contentColor = textColor
            )
        }
    }
}

