    DomainConditionChip(label = "Stretched from its average", direction = "BEARISH", category = "VOLATILITY")
)

@Preview(name = "Light", showBackground = true)
@Composable
private fun PreviewConditionChipRowLight() {
    MarketPulseTheme(theme = MarketPulseTheme.NAVY) {
        // Constrained width so the wrap-to-a-second-line behavior is actually visible here,
        // rather than an unbounded Row letting every chip sit on one line.
        ConditionChipRow(
            chips = previewChips,
            modifier = Modifier
                .fillMaxWidth()
                .padding(dimensionResource(id = R.dimen.padding_large))
        )
    }
}

